data = sys.stdin.read().split()
r, c, h, w = int(data[0]), int(data[1]), int(data[2]), int(data[3])
g = data[4:4 + r]
cov = [[False] * c for _ in range(r)]
for i in range(r - h + 1):
    for j in range(c - w + 1):
        ok = True
        for a in range(i, i + h):
            for b in range(j, j + w):
                if g[a][b] == '1':
                    ok = False
        if ok:
            for a in range(i, i + h):
                for b in range(j, j + w):
                    cov[a][b] = True
res = True
for i in range(r):
    for j in range(c):
        if g[i][j] == '0' and not cov[i][j]:
            res = False
print('true' if res else 'false')

